60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
72	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
73	     * and a dotted domain (e.g. {@code not-an-email}).
74	     */
75	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
76	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
77	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
78	
79	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
80	    private static final String DEFAULT_COUNTRY_CODE = "61";
81	
82	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
86	    private static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
89	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
90	
91	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
92	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
93	
94	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
95	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
96	        "ST", "STREET",
97	        "RD", "ROAD",
98	        "AVE", "AVENUE");
99	
100	    private final ClinicService clinicService;
101	
102	    private final OwnerMapper ownerMapper;
103	
104	    private final PetMapper petMapper;
105	
106	    private final VisitMapper visitMapper;
107	
108	    public OwnerRestControllerV1(ClinicService clinicService,
109	                                 OwnerMapper ownerMapper,
110	                                 PetMapper petMapper,
111	                                 VisitMapper visitMapper) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        List<String> missingFields = new ArrayList<>();
147	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
148	            missingFields.add("firstName");
149	        }
150	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
151	            missingFields.add("lastName");
152	        }
153	        // Normalize the address up front; the required-field check rejects it when it is blank
154	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
155	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
156	        if (!StringUtils.hasText(normalizedAddress)) {
157	            missingFields.add("address");
158	        }
159	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
160	            missingFields.add("city");
161	        }
162	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
163	            missingFields.add("telephone");
164	        }
165	        if (!missingFields.isEmpty()) {
166	            throw new InvalidRequestException(missingFields);
167	        }
168	        HttpHeaders headers = new HttpHeaders();
169	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
170	        // Store (and later return) the normalized address computed above.
171	        owner.setAddress(normalizedAddress);
172	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
173	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
174	        owner.setTelephone(normalizedTelephone);
175	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
176	        owner.setEmail(normalizeEmail(owner.getEmail()));
177	        // Default the (optional) registration date to the server's current date when none was supplied.
178	        if (owner.getRegistrationDate() == null) {
179	            owner.setRegistrationDate(LocalDate.now());
180	        }
181	        // The effective registration date must fall on a business day: when it lands on a Saturday or
182	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
183	        // derived from the registration date below (daily create-limit, membership number) uses this
184	        // adjusted date.
185	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
186	        // Reject the request once the maximum number of owners for the owner's registration day has
187	        // been reached (100 or more owners already created on that date).
188	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
189	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
190	        }
191	        // Reject the request when the owner's city has already reached its owner capacity.
192	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
193	            throw new CityCapacityException(owner.getCity());
194	        }
195	        // Reject the request if the E.164 telephone is already used by another owner.
196	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
197	            throw new DuplicateTelephoneException(normalizedTelephone);
198	        }
199	        // Reject the request if another owner already shares the same last name and address
200	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
201	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
202	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
203	        // every existing member that does not yet carry it.
204	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
205	        if (!householdMembers.isEmpty()) {
206	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
207	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
208	            }
209	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
210	            owner.setHouseholdId(householdId);
211	            for (Owner member : householdMembers) {
212	                if (!householdId.equals(member.getHouseholdId())) {
213	                    member.setHouseholdId(householdId);
214	                    this.clinicService.saveOwner(member);
215	                }
216	            }
217	        }
218	        // Record how many existing owners already share this first name and last name
219	        // (compared case-insensitively) before this owner is created.
220	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
221	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
222	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
223	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
224	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
225	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
226	        this.clinicService.saveOwner(owner);
227	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
228	        headers.setLocation(UriComponentsBuilder.newInstance()
229	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
230	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
236	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
237	        if (currentOwner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        currentOwner.setAddress(ownerFieldsDto.getAddress());
241	        currentOwner.setCity(ownerFieldsDto.getCity());
242	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
243	        currentOwner.setLastName(ownerFieldsDto.getLastName());
244	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
245	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
246	        this.clinicService.saveOwner(currentOwner);
247	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
248	    }
249	
250	    /**
251	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
252	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
253	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
254	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
255	     *
256	     * @param city     the owner's city
257	     * @param lastName the owner's last name
258	     * @return the generated customer code
259	     */
260	    private String generateCustomerCode(String city, String lastName) {
261	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
262	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
263	        String normalizedCity = normalizeForComparison(city);
264	        int sequence = (int) this.clinicService.findAllOwners().stream()
265	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
266	            .count() + 1;
267	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
268	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
269	    }
270	
271	    /**
272	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
273	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
274	     * that is stored, returned and used for every value derived from it.
275	     *
276	     * @param date the effective registration date (supplied or defaulted)
277	     * @return the same date when it is a weekday, otherwise the next Monday
278	     */
279	    private LocalDate rollToBusinessDay(LocalDate date) {
280	        DayOfWeek dayOfWeek = date.getDayOfWeek();
281	        if (dayOfWeek == DayOfWeek.SATURDAY) {
282	            return date.plusDays(2);
283	        }
284	        if (dayOfWeek == DayOfWeek.SUNDAY) {
285	            return date.plusDays(1);
286	        }
287	        return date;
288	    }
289	
290	    /**
291	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
292	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
293	     *
294	     * @param customerCode     the owner's already-assigned customer code
295	     * @param registrationDate the owner's registration date
296	     * @return the generated membership number
297	     */
298	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
299	        String yy = String.format("%02d", registrationDate.getYear() % 100);
300	        return String.format("%s-M%s", customerCode, yy);
301	    }
302	
303	    /**
304	     * Count the existing owners that share the given first name and last name, comparing each
305	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
306	     * yet persisted, so it is not included in the count.
307	     *
308	     * @param firstName the incoming owner's first name
309	     * @param lastName  the incoming owner's last name
310	     * @return the number of existing namesakes
311	     */
312	    private int countNamesakes(String firstName, String lastName) {
313	        String normalizedFirstName = normalizeForComparison(firstName);
314	        String normalizedLastName = normalizeForComparison(lastName);
315	        return (int) this.clinicService.findAllOwners().stream()
316	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
317	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
318	            .count();
319	    }
320	
321	    /**
322	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
323	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
324	     *
325	     * @param city the incoming owner's city
326	     * @return the number of existing owners already in that city
327	     */
328	    private int countOwnersInCity(String city) {
329	        String normalizedCity = normalizeForComparison(city);
330	        return (int) this.clinicService.findAllOwners().stream()
331	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
332	            .count();
333	    }
334	
335	    /**
336	     * Count the existing owners whose registration date equals the given date. The incoming owner is
337	     * not yet persisted, so it is not included in the count.
338	     *
339	     * @param registrationDate the incoming owner's registration date
340	     * @return the number of existing owners already registered on that date
341	     */
342	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
343	        return (int) this.clinicService.findAllOwners().stream()
344	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
345	            .count();
346	    }
347	
348	    /**
349	     * Find the existing owners that live in the same household as the given values, i.e. those that
350	     * share both the last name and the address when each is compared case-insensitively with
351	     * collapsed whitespace.
352	     *
353	     * @param lastName the incoming owner's last name
354	     * @param address  the incoming owner's address
355	     * @return the matching existing owners (possibly empty)
356	     */
357	    private List<Owner> findHouseholdMembers(String lastName, String address) {
358	        String normalizedLastName = normalizeForComparison(lastName);
359	        String normalizedAddress = normalizeForComparison(address);
360	        return this.clinicService.findAllOwners().stream()
361	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
362	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
363	            .toList();
364	    }
365	
366	    /**
367	     * Generate a stable shared household identifier for the given last name and address. The value is
368	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
369	     * and address, so every owner joining the same household resolves to the same identifier. It is the
370	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
371	     *
372	     * @param lastName the household's last name
373	     * @param address  the household's address
374	     * @return the stable household identifier
375	     */
376	    private String generateHouseholdId(String lastName, String address) {
377	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
378	        try {
379	            byte[] digest = MessageDigest.getInstance("SHA-256")
380	                .digest(key.getBytes(StandardCharsets.UTF_8));
381	            StringBuilder sb = new StringBuilder(digest.length * 2);
382	            for (byte b : digest) {
383	                sb.append(String.format("%02x", b));
384	            }
385	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
386	        } catch (java.security.NoSuchAlgorithmException e) {
387	            throw new IllegalStateException("SHA-256 not available", e);
388	        }
389	    }
390	
391	    /**
392	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
393	     * single space, upper-case the result and expand common street-type abbreviations token by token
394	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
395	     * to the empty string. The result is the canonical form that is stored, returned and used for every
396	     * address comparison (household duplicate detection and the shared household id).
397	     *
398	     * @param address the raw address, may be {@code null}
399	     * @return the normalized address
400	     */
401	    private String normalizeAddress(String address) {
402	        if (address == null) {
403	            return "";
404	        }
405	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
406	        if (collapsed.isEmpty()) {
407	            return "";
408	        }
409	        String[] tokens = collapsed.split(" ");
410	        StringBuilder sb = new StringBuilder(collapsed.length());
411	        for (int i = 0; i < tokens.length; i++) {
412	            if (i > 0) {
413	                sb.append(' ');
414	            }
415	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
416	        }
417	        return sb.toString();
418	    }
419	
420	    /**
421	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
422	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
423	     *
424	     * @param value the raw value, may be {@code null}
425	     * @return the normalized value
426	     */
427	    private String normalizeForComparison(String value) {
428	        if (value == null) {
429	            return "";
430	        }
431	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
432	    }
433	
434	    /**
435	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
436	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
437	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
438	     * is returned lower-cased.
439	     *
440	     * @param email the raw email from the request payload, may be {@code null}
441	     * @return the lower-cased email, or {@code null} when none was provided
442	     */
443	    private String normalizeEmail(String email) {
444	        if (!StringUtils.hasText(email)) {
445	            return null;
446	        }
447	        if (!EMAIL_PATTERN.matcher(email).matches()) {
448	            throw new InvalidRequestException(List.of("email"));
449	        }
450	        return email.toLowerCase(Locale.ROOT);
451	    }
452	
453	    /**
454	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
455	     * already carries a leading '+' keeps its country code; otherwise the default country code
456	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
457	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
458	     * is thrown (mapped to 400 Bad Request).
459	     *
460	     * @param telephone the raw telephone from the request payload
461	     * @return the E.164 string (e.g. {@code +61412345678})
462	     */
463	    private String normalizeTelephone(String telephone) {
464	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
465	        String candidate;
466	        if (cleaned.startsWith("+")) {
467	            candidate = cleaned;
468	        } else {
469	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
470	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
471	        }
472	        if (!E164_PATTERN.matcher(candidate).matches()) {
473	            throw new InvalidRequestException(List.of("telephone"));
474	        }
475	        return candidate;
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Transactional
480	    @Override
481	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
482	        Owner owner = this.clinicService.findOwnerById(ownerId);
483	        if (owner == null) {
484	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
485	        }
486	        this.clinicService.deleteOwner(owner);
487	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
488	    }
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Override
492	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
493	        Owner owner = this.clinicService.findOwnerById(ownerId);
494	        if (owner == null) {
495	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	        }
497	        HttpHeaders headers = new HttpHeaders();
498	        Pet pet = petMapper.toPet(petFieldsDto);
499	        owner.setId(ownerId);
500	        pet.setOwner(owner);
501	        pet.getType().setName(null);
502	        this.clinicService.savePet(pet);
503	        PetDto petDto = petMapper.toPetDto(pet);
504	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
505	            .buildAndExpand(pet.getId()).toUri());
506	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Override
511	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
512	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
513	        if (currentOwner != null) {
514	            Pet currentPet = this.clinicService.findPetById(petId);
515	            if (currentPet != null) {
516	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
517	                currentPet.setName(petFieldsDto.getName());
518	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
519	                this.clinicService.savePet(currentPet);
520	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
521	            }
522	        }
523	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
524	    }
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
529	        HttpHeaders headers = new HttpHeaders();
530	        Visit visit = visitMapper.toVisit(visitFieldsDto);
531	        Pet pet = new Pet();
532	        pet.setId(petId);
533	        visit.setPet(pet);
534	        this.clinicService.saveVisit(visit);
535	        VisitDto visitDto = visitMapper.toVisitDto(visit);
536	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
537	            .buildAndExpand(visit.getId()).toUri());
538	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
539	    }
540	
541	
542	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
543	    @Override
544	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
545	        Owner owner = this.clinicService.findOwnerById(ownerId);
546	        if (owner != null) {
547	            Pet pet = owner.getPet(petId);
548	            if (pet != null) {
549	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
550	            }
551	        }
552	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
553	    }
554	}
